block.template:
{# Beispiel 3 · Kennzahlen: Liste mit for-Schleife, number formatiert in der Sprache der Seite. #}
{% if title or block.editing %}<h2 class="kz__title" id="{{ block.title_id }}">{{ title }}</h2>{% endif %}
<ul class="kz" role="list">
  {% for z in zahlen %}
  <li class="kz__item">
    <span class="kz__num">{{ z.wert | number }}{% if z.zusatz %}<span class="kz__unit">{{ z.zusatz }}</span>{% endif %}</span>
    <span class="kz__label">{{ z.label }}</span>
  </li>
  {% else %}
  {% if block.editing %}<li class="kz__item">Noch keine Kennzahlen – in der Seitenleiste „Kennzahl hinzufügen“.</li>{% endif %}
  {% endfor %}
</ul>

block.css:
.kz__title { margin: 0 0 1.5rem; }
.kz {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 11rem), 1fr));
  gap: var(--cb-gap);
  margin: 0;
  padding: 0;
  list-style: none;
}
.kz__item {
  display: flex;
  flex-direction: column;
  gap: .35rem;
  padding: 1.25rem;
  border: 1px solid var(--cb-line);
  border-radius: var(--cb-radius);
  background: var(--cb-surface);
  box-shadow: inset 0 .25rem 0 var(--cb-accent);
}
.kz__num { font-size: clamp(2rem, 5vw, 2.75rem); font-weight: 700; line-height: 1.05; font-variant-numeric: tabular-nums; }
.kz__unit { margin-left: .1em; font-size: .6em; }
.kz__label { color: var(--cb-muted); }
